import java.sql.*;import java.util.*;public class Main{public static void main(String[]a){try(Connection c=DatabaseConnection.getConnection()){c.createStatement().executeUpdate("CREATE TABLE IF NOT EXISTS students(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,roll_no VARCHAR(30) UNIQUE NOT NULL,department VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(20) NOT NULL,marks DECIMAL(5,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");}catch(SQLException e){System.out.println("Database error: "+e.getMessage());return;}new UI(new Scanner(System.in),new AdminService(new StudentDAO())).start();}}
